  modified:
    %cond2
      source: %cond2 = icmp samesign ugt i32 %x, %ext
      target: %cond2 = icmp ugt i8 %0, %ce.arg0
    %res
      source: %res = phi i8 [ %call1, %else ], [ %ce.arg0, %for.body ]
